// ===========================================================================
//  SỔ LUẬN ĐIỂM - khai mỗi mã đang giữ/cân nhắc: VÌ SAO mua + ĐIỀU GÌ làm mình SAI.
//  Hệ thống canh các điều kiện SAI và nhắc xem lại định kỳ.
//  ⚠️ Sửa khối THESES dưới đây theo danh mục THẬT của anh.
// ===========================================================================
const THESES = {
  'BID': {
    thesis: 'NH quốc doanh, định giá rẻ so lịch sử (P/E ~9 vs TB5N ~13), kỳ vọng khối ngoại quay lại.',
    invalidate: 'Nợ xấu (NPL) tăng mạnh / NIM co lại / khối ngoại xả kéo dài.',
    entryDate: '2026-06-13', reviewDate: '2026-09-13',
    priceFloor: 39,      // rớt dưới mức này = luận điểm sai (cắt lỗ)
    peCeiling: 14,       // P/E vượt mức này = hết rẻ, luận điểm "rẻ" không còn
    foreignSellAlert: true,
  },
  'FPT': {
    thesis: 'Công nghệ tăng trưởng, P/E ~13 thấp bất thường so lịch sử (TB5N ~20).',
    invalidate: 'Tăng trưởng doanh thu/LN chậm lại rõ rệt / P/E hết chiết khấu.',
    entryDate: '2026-06-13', reviewDate: '2026-09-13',
    priceFloor: 0, peCeiling: 20, foreignSellAlert: true,
  },
  // Thêm mã của anh theo mẫu trên. priceFloor/peCeiling = 0 để bỏ qua kiểm tra đó.
};
// ===========================================================================

const tickers = Object.keys(THESES);
if (!tickers.length) {
  return [{ json: { hasReport: true, message: '📓 *SỔ LUẬN ĐIỂM*\n\nChưa khai luận điểm nào. Mở node này, thêm mỗi mã anh đang giữ kèm: *vì sao mua* + *điều gì làm mình sai* + giá sàn/trần P/E. Hệ thống sẽ canh giúp.' } }];
}

const to = Math.floor(Date.now() / 1000);
const from = to - 60 * 60 * 24 * 60;
const todayStr = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFin = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };

const fetchPrice = async (t) => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock', qs: { symbol: t, from, to, resolution: '1D' }, headers: hBar, json: true, timeout: 15000 });
    if (res && Array.isArray(res.c) && res.c.length) return res.c[res.c.length - 1];
  } catch (e) { /* */ }
  return null;
};
const fetchPE = async (t) => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + t + '~itemCode:51006&sort=reportDate:desc&size=3', headers: hFin, json: false, timeout: 15000 });
    let p; try { p = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { p = null; }
    const d = (p && p.data) || [];
    return d.length ? d[0].value : null;
  } catch (e) { return null; }
};
const fetchForeignStreak = async (t) => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + t + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 15000 });
    const nets = ((res && res.data) || []).map(x => (x.netVal || 0) / 1e9);
    if (!nets.length) return { streak: 0, dir: 0 };
    const dir = nets[0] > 1 ? 1 : nets[0] < -1 ? -1 : 0;
    let streak = 0; for (const v of nets) { const s = v > 1 ? 1 : v < -1 ? -1 : 0; if (s === dir && dir !== 0) streak++; else break; }
    return { streak, dir };
  } catch (e) { return { streak: 0, dir: 0 }; }
};
const daysBetween = (a, b) => Math.round((new Date(b) - new Date(a)) / 86400000);
const fmtD = (k) => Math.round(k * 1000).toLocaleString('vi-VN') + 'đ';

const blocks = [];
let redCount = 0;
for (const t of tickers) {
  const th = THESES[t];
  const price = await fetchPrice(t);
  const pe = await fetchPE(t);
  const fg = await fetchForeignStreak(t);

  const flags = [];
  const health = [];
  if (price != null) {
    if (th.priceFloor > 0 && price <= th.priceFloor) { flags.push('🔴 GIÁ thủng sàn luận điểm ' + fmtD(th.priceFloor) + ' → đây là tín hiệu CẮT LỖ / luận điểm sai'); }
    else if (th.priceFloor > 0) { health.push('giá ' + fmtD(price) + ' (sàn ' + fmtD(th.priceFloor) + ', còn cách ' + ((price / th.priceFloor - 1) * 100).toFixed(1) + '%)'); }
    else { health.push('giá ' + fmtD(price)); }
  }
  if (pe != null && th.peCeiling > 0) {
    if (pe >= th.peCeiling) flags.push('🟠 P/E ' + pe.toFixed(1) + ' vượt trần ' + th.peCeiling + ' → luận điểm "rẻ" KHÔNG còn');
    else health.push('P/E ' + pe.toFixed(1) + ' (trần ' + th.peCeiling + ' ✓)');
  }
  if (th.foreignSellAlert && fg.dir === -1 && fg.streak >= 3) flags.push('🟠 Khối ngoại XẢ ' + fg.streak + ' phiên liên tiếp');
  else if (fg.streak >= 3) health.push('KN ' + (fg.dir > 0 ? 'gom' : 'xả') + ' ' + fg.streak + ' phiên');

  const dRev = th.reviewDate ? daysBetween(todayStr, th.reviewDate) : null;
  if (dRev != null && dRev <= 0) flags.push('🟠 ĐÃ ĐẾN HẠN xem lại luận điểm (' + th.reviewDate + ')');

  if (flags.length) redCount++;
  let b = '📌 *' + t + '*' + (th.entryDate ? ' _(vào ' + th.entryDate.split('-').reverse().slice(0,2).join('/') + (dRev != null ? ', xem lại sau ' + Math.max(0, dRev) + ' ngày' : '') + ')_' : '');
  b += '\n   *Vì sao:* ' + th.thesis;
  b += '\n   *Sẽ SAI nếu:* ' + th.invalidate;
  if (health.length) b += '\n   Sức khoẻ: ' + health.join(' · ');
  b += flags.length ? '\n   ' + flags.join('\n   ') + '\n   → ⚠️ *XEM LẠI LUẬN ĐIỂM*' : '\n   → ✅ Luận điểm còn nguyên vẹn';
  blocks.push(b);
}

const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const head = '📓 *SỔ LUẬN ĐIỂM — review tuần*\n_' + now + '_\n'
  + (redCount ? '⚠️ *' + redCount + ' mã có cờ cần xem lại*\n\n' : '_Tất cả luận điểm còn nguyên vẹn._\n\n');
const foot = '\n\n_Đọc lại luận điểm mỗi tuần là kỷ luật chống "yêu một mã". Cờ ⚠️ = điều kiện SAI anh tự đặt đã chạm — hãy bán hoặc viết lại luận điểm, đừng lờ đi._';

return [{ json: { hasReport: true, message: head + blocks.join('\n\n') + foot } }];

const full = $input.first().json.message || '';
const SIZE = 3800;
const parts = [];
let s = full;
while (s.length > SIZE) { let cut = s.lastIndexOf('\n', SIZE); if (cut < SIZE * 0.5) cut = SIZE; parts.push(s.slice(0, cut)); s = s.slice(cut); }
if (s.trim()) parts.push(s);
return parts.map(p => ({ json: { message: p } }));
